# =========================
# CYBERPUNK NEON USER CENTER
# =========================
def render_cyberpunk_user_center(trial_users, key_users):
    total_trial = len(trial_users)
    total_key = len(key_users)
    total_users = total_trial + total_key

    def neon_bar(value, maximum=10):
        maximum = max(maximum, 1)
        filled = min(10, round((value / maximum) * 10))
        return "█" * filled + "░" * (10 - filled)

    trial_rows = []
    for i, user in enumerate(trial_users, 1):
        name = user.get("name") or user.get("username") or "UNKNOWN USER"
        uid = user.get("id") or user.get("user_id") or "-"
        status = user.get("status") or "TRIAL ACTIVE"
        trial_rows.append(
            f"│ {i:02d} │ 👤 {name[:18]:18} │ 🆔 {str(uid)[:12]:12} │ {status[:16]:16} │"
        )

    key_rows = []
    for i, user in enumerate(key_users, 1):
        name = user.get("name") or user.get("username") or "UNKNOWN USER"
        uid = user.get("id") or user.get("user_id") or "-"
        key = user.get("key") or user.get("access_key") or "NO KEY"
        status = user.get("status") or "ACTIVE"
        key_rows.append(
            f"│ {i:02d} │ 🔑 {name[:14]:14} │ 🆔 {str(uid)[:10]:10} │ {key[:18]:18} │ {status[:10]:10} │"
        )

    if not trial_rows:
        trial_rows = ["│             ◈ NO TRIAL USERS DETECTED IN DATABASE ◈              │"]

    if not key_rows:
        key_rows = ["│           ◈ NO BUYER / FILE KEY USERS DETECTED ◈            │"]

    trial_rows_text = "\n".join(trial_rows)
    key_rows_text = "\n".join(key_rows)

    return f"""
╔══════════════════════════════════════════════════════════════╗
║        ⚡ M A S K Y Y O F F C  //  USER CENTER ⚡          ║
║              C Y B E R P U N K   N E O N                    ║
╠══════════════════════════════════════════════════════════════╣
║  🟣 SYSTEM STATUS : ONLINE        ⚡ DATABASE : SYNCED       ║
╠══════════════════════════════════════════════════════════════╣
║  👥 TOTAL USERS   : {total_users:>6}   [{neon_bar(total_users, max(total_users, 1))}]      ║
║  🆓 TRIAL USERS   : {total_trial:>6}   [{neon_bar(total_trial, max(total_users, 1))}]      ║
║  🔑 KEY USERS     : {total_key:>6}   [{neon_bar(total_key, max(total_users, 1))}]      ║
╚══════════════════════════════════════════════════════════════╝

╔═══════════════ 🆓 TRIAL USER DATABASE 🆓 ═══════════════════╗
{trial_rows_text}
╚══════════════════════════════════════════════════════════════╝

╔════════════ 🔑 KEY BUYERS & FILE KEYS 🔑 ═══════════════════╗
{key_rows_text}
╚══════════════════════════════════════════════════════════════╝

┌──────────────────────────────────────────────────────────────┐
│  ◈ QUICK GUIDE                                               │
│  🆓 TRIAL USERS  → Pengguna akses trial/free                 │
│  🔑 KEY USERS    → Pembeli key + key yang tersimpan di file  │
│  🟢 ACTIVE       → Key dapat digunakan                       │
│  🔴 LOCKED       → Key diblokir sementara                    │
└──────────────────────────────────────────────────────────────┘
"""

